SELECT 
FROM crm_high_seas_record
WHERE deleted = 0

    AND customer_id = #{reqVO.customerId}


    AND action_type = #{reqVO.actionType}


    AND action_time >= #{reqVO.beginTime}


    AND action_time <= #{reqVO.endTime}

